public abstract class OatHeader : StructConverter {

	protected string magic;
	protected string version;

	protected List<string> orderedKeyList = new List<string>();//ordered as defined
	protected Map<string, string> key_value_store_ = new Dictionary<string, string>();

	protected List<OatDexFile> oatDexFileList = new List<OatDexFile>();

	/**
	 * Base constructor for the OAT headers.
	 * @param reader the binary reader with the file bytes.
	 * @throws IOException if an IO exception occurs.
	 */
	protected OatHeader(BinaryReader reader)
